import{_ as d,c as a,a2 as e,o as r}from"./chunks/framework.Bzjhwp8w.js";const b=JSON.parse('{"title":"Langflow中的输入和输出组件","description":"Langflow中的输入和输出组件","frontmatter":{"title":"Langflow中的输入和输出组件","description":"Langflow中的输入和输出组件","layout":"doc"},"headers":[],"relativePath":"langflow/components-io.md","filePath":"langflow/components-io.md"}'),o={name:"langflow/components-io.md"};function h(n,t,s,u,l,i){return r(),a("div",null,t[0]||(t[0]=[e('<h1 id="langflow中的输入和输出组件" tabindex="-1">Langflow中的输入和输出组件 <a class="header-anchor" href="#langflow中的输入和输出组件" aria-label="Permalink to &quot;Langflow中的输入和输出组件&quot;">​</a></h1><p>这一类别的组件定义了数据在您的流程中进入和退出的位置。它们动态地改变Playground（游乐场）并且可以被重命名，以便于构建和维护您的流程。</p><p>Chat Input（聊天输入）和Text Input（文本输入）组件之间的区别在于输出格式、可配置字段的数量以及它们在Playground中的显示方式。</p><h2 id="chat-input" tabindex="-1">Chat Input <a class="header-anchor" href="#chat-input" aria-label="Permalink to &quot;Chat Input&quot;">​</a></h2><p>该组件用于收集来自聊天的用户输入。</p><p>Chat Input 组件创建一个 <a href="./URL.html">Message</a> (消息) 对象，该对象包括输入文本、发送者信息、会话 ID、文件附件和样式属性。它可以选择性地将消息存储在聊天历史记录中，并支持自定义消息的外观。</p><h3 id="inputs" tabindex="-1">Inputs <a class="header-anchor" href="#inputs" aria-label="Permalink to &quot;Inputs&quot;">​</a></h3><table tabindex="0"><thead><tr><th>名称</th><th>显示名称</th><th>信息</th><th>类型</th></tr></thead><tbody><tr><td>input_value</td><td>文本</td><td>作为输入传递的消息。</td><td>MultilineInput</td></tr><tr><td>should_store_message</td><td>存储消息</td><td>在历史记录中存储消息。</td><td>BoolInput</td></tr><tr><td>sender</td><td>发送者类型</td><td>发送者的类型。</td><td>DropdownInput</td></tr><tr><td>sender_name</td><td>发送者名称</td><td>发送者的名称。</td><td>MessageTextInput</td></tr><tr><td>session_id</td><td>会话 ID</td><td>聊天的会话 ID。如果为空，将使用当前会话 ID 参数。</td><td>MessageTextInput</td></tr><tr><td>files</td><td>文件</td><td>随消息发送的文件。</td><td>FileInput</td></tr><tr><td>background_color</td><td>背景颜色</td><td>图标的背景颜色。</td><td>MessageTextInput</td></tr><tr><td>chat_icon</td><td>图标</td><td>消息的图标。</td><td>MessageTextInput</td></tr><tr><td>text_color</td><td>文本颜色</td><td>名称的文本颜色。</td><td>MessageTextInput</td></tr></tbody></table><h3 id="outputs" tabindex="-1">Outputs <a class="header-anchor" href="#outputs" aria-label="Permalink to &quot;Outputs&quot;">​</a></h3><table tabindex="0"><thead><tr><th>名称</th><th>显示名称</th><th>信息</th></tr></thead><tbody><tr><td>message</td><td>Message</td><td>包含所有指定属性的结果聊天消息对象。</td></tr></tbody></table><h2 id="文本输入" tabindex="-1">文本输入 <a class="header-anchor" href="#文本输入" aria-label="Permalink to &quot;文本输入&quot;">​</a></h2><p>文本输入组件在Playground中添加一个输入字段。</p><p>文本输入组件提供一个文本输入字段，而聊天输入组件则有多个字段用于各种与聊天相关的功能。</p><h3 id="inputs-1" tabindex="-1">Inputs <a class="header-anchor" href="#inputs-1" aria-label="Permalink to &quot;Inputs&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Name</th><th>Display Name</th><th>Info</th><th>Type</th></tr></thead><tbody><tr><td>input_value</td><td>Text</td><td>要作为输入传递的文本。</td><td>MultilineInput</td></tr></tbody></table><h3 id="outputs-1" tabindex="-1">Outputs <a class="header-anchor" href="#outputs-1" aria-label="Permalink to &quot;Outputs&quot;">​</a></h3><table tabindex="0"><thead><tr><th>名称</th><th>显示名称</th><th>信息</th></tr></thead><tbody><tr><td>text</td><td>Text</td><td>生成的文本消息。</td></tr></tbody></table><h2 id="chat-output" tabindex="-1">Chat Output <a class="header-anchor" href="#chat-output" aria-label="Permalink to &quot;Chat Output&quot;">​</a></h2><p><code>Chat Output</code> 组件创建一个 <a href="./URL.html">消息</a> 对象，该对象包括输入文本、发送者信息、会话ID和样式属性。它可以选择性地将消息存储在聊天历史中，并支持对消息外观的自定义，包括背景颜色、图标和文本颜色。</p><h3 id="inputs-2" tabindex="-1">Inputs <a class="header-anchor" href="#inputs-2" aria-label="Permalink to &quot;Inputs&quot;">​</a></h3><table tabindex="0"><thead><tr><th>名称</th><th>显示名称</th><th>信息</th><th>类型</th></tr></thead><tbody><tr><td>input_value</td><td>文本</td><td>要作为输出传递的消息。</td><td>MessageInput</td></tr><tr><td>should_store_message</td><td>存储消息</td><td>将消息存储在历史记录中。</td><td>BoolInput</td></tr><tr><td>sender</td><td>发送者类型</td><td>发送者的类型。</td><td>DropdownInput</td></tr><tr><td>sender_name</td><td>发送者名称</td><td>发送者的名称。</td><td>MessageTextInput</td></tr><tr><td>session_id</td><td>会话 ID</td><td>聊天的会话 ID。如果为空，将使用当前会话 ID 参数。</td><td>MessageTextInput</td></tr><tr><td>data_template</td><td>数据模板</td><td>转换数据为文本的模板。如果留空，将动态设置为数据的 text 键。</td><td>MessageTextInput</td></tr><tr><td>background_color</td><td>背景颜色</td><td>图标的背景颜色。</td><td>MessageTextInput</td></tr><tr><td>chat_icon</td><td>图标</td><td>消息的图标。</td><td>MessageTextInput</td></tr><tr><td>text_color</td><td>文本颜色</td><td>名称的文本颜色。</td><td>MessageTextInput</td></tr></tbody></table><h3 id="outputs-2" tabindex="-1">Outputs <a class="header-anchor" href="#outputs-2" aria-label="Permalink to &quot;Outputs&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Name</th><th>Display Name</th><th>Info</th></tr></thead><tbody><tr><td>message</td><td>Message</td><td>结果聊天消息对象，包含所有指定的属性。</td></tr></tbody></table><h2 id="text-output" tabindex="-1">文本输出 <a class="header-anchor" href="#text-output" aria-label="Permalink to &quot;文本输出 {#text-output}&quot;">​</a></h2><p><code>TextOutputComponent</code> 在 <strong>Playground</strong> 中显示文本输出。它接受一个文本输入，并返回一个包含该文本的 <a href="/dllm/concepts-objects.html">Message</a> 对象。与聊天输出相比，该组件更简单，专注于显示文本，而不包含额外的聊天特定功能或自定义选项。</p><h3 id="输入" tabindex="-1">输入 <a class="header-anchor" href="#输入" aria-label="Permalink to &quot;输入&quot;">​</a></h3><table tabindex="0"><thead><tr><th>名称</th><th>显示名称</th><th>信息</th><th>类型</th></tr></thead><tbody><tr><td>input_value</td><td>文本</td><td>作为输出传递的文本。</td><td>MultilineInput</td></tr></tbody></table><h3 id="输出" tabindex="-1">输出 <a class="header-anchor" href="#输出" aria-label="Permalink to &quot;输出&quot;">​</a></h3><table tabindex="0"><thead><tr><th>名称</th><th>显示名称</th><th>信息</th></tr></thead><tbody><tr><td>text</td><td>Text</td><td>结果文本消息。</td></tr></tbody></table>',29)]))}const c=d(o,[["render",h]]);export{b as __pageData,c as default};
